50	        roles.refuseViewer(sheetId, user);
51	        if (to.isBefore(from)) {
52	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's to-date cannot be before its from-date.");
53	        }
54	        sheets.load(sheetId, user);
55	        // hold the sheet so two periods added at the same moment are checked one after the other
56	        sheetRows.findLockedById(sheetId);
57	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
58	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
59	        }
60	        if (periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, to, from)) {
61	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
62	        }
63	        Period added;
64	        try {
65	            added = periods.saveAndFlush(new Period(sheetId, name, from, to));
66	        } catch (DataIntegrityViolationException e) {
67	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
68	        }
69	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName() + " from="
70	                + added.getFromDate() + " to=" + added.getToDate());
