90	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
91	            String name = month.toString();
92	            LocalDate first = month.atDay(1);
93	            LocalDate last = month.atEndOfMonth();
94	            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)
95	                    || periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, last, first)) {
