97	            }
98	            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
99	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
100	                    + " from=" + added.getFromDate() + " to=" + added.getToDate());
101	            made.add(added);
